SELECT /*selectBuyerMdAmBudgetList*/ ROWNUM AS No, -- 0 Y.DEPT_NAME, -- 1 Y.ACCOUNT_TYPE_TEXT, -- 2 계정분류명 Y.TERM_TYPE_TEXT, -- 3 기간구분 Y.TERM_TEXT, -- 4 Y.PLAN_AMT, -- 5 예산 Y.RESULT_AMT, -- 6 실적금액 Y.TEMP_AMT_TEXT, -- 7 잔액 Y.REMARK , -- 8 비고 Y.PLAN_DATE , -- 9 예산수립일 Y.LAST_RESULT_DATE , -- 10 최종실적발생일 Y.TEMP_AMT , -- 11 임시실적금액 Y.TERM , -- 12 기간 Y.FROM_DATE , -- 13 시작일 Y.TO_DATE , -- 14 종료일 Y.DEPT , -- 15 부서코드 Y.ACCOUNT_TYPE , -- 16 계정코드 Y.TERM_TYPE , -- 17 기간구분코드 Y.CHECK_VALUE, -- 18 Y.ORG_DEPT_CODE, -- 19 Y.ORG_ACCOUNT_TYPE, -- 20 Y.ORG_TERM -- 21 ,Y.BUYER -- 고객사코드 ,Y.BUYER_NAME -- 고객사명 FROM ( SELECT ROWNUM NUM , X.DEPT_NAME, X.ACCOUNT_TYPE_TEXT, X.TERM_TYPE_TEXT, X.TERM_TEXT, X.PLAN_AMT, X.RESULT_AMT, X.TEMP_AMT_TEXT, X.REMARK, X.PLAN_DATE, X.LAST_RESULT_DATE, X.TEMP_AMT, X.TERM , X.FROM_DATE, X.TO_DATE, X.DEPT, X.ACCOUNT_TYPE, X.TERM_TYPE, X.CHECK_VALUE, X.ORG_DEPT_CODE, X.ORG_ACCOUNT_TYPE, X.ORG_TERM ,X.BUYER ,X.BUYER_NAME FROM ( SELECT (SELECT C.TEXT1 FROM ICOMCOD2 C WHERE C.COMPANY_CODE = BUYER AND C.CODE = DEPT AND C.TYPE = 'C001') DEPT_NAME,-- 1 (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.COMPANY_CODE = BUYER AND C.CODE = ACCOUNT_TYPE AND C.TYPE = 'Z014') ACCOUNT_TYPE_TEXT, -- 2 DECODE(TERM_TYPE,'Y','년','H','반기','Q','분기','M','월','') TERM_TYPE_TEXT, -- 3 SUBSTR(TERM,0,4)||DECODE(SUBSTR(TERM,5,2),'H1','년도 상반기','H2','년도 하반기' ,'Q1','년도 1/4분기','Q2','년도 2/4분기' ,'Q3','년도 3/4분기','Q4','년도 4/4분기' ,'01','년도 1월','02','년도 2월' ,'03','년도 3월','04','년도 4월' ,'05','년도 5월','06','년도 6월' ,'07','년도 7월','08','년도 8월' ,'09','년도 9월','10','년도 10월' ,'11','년도 11월','12','년도 12월' ,'년도') TERM_TEXT, -- 4 NVL(PLAN_AMT,'0') PLAN_AMT, -- 5 NVL(RESULT_AMT,'0') RESULT_AMT, -- 6 NVL(PLAN_AMT,'0') - (NVL(RESULT_AMT,'0')+ NVL(TEMP_AMT,'0')) TEMP_AMT_TEXT, -- 7 REMARK , -- 8 PLAN_DATE , -- 9 LAST_RESULT_DATE , -- 10 NVL(TEMP_AMT,'0') AS TEMP_AMT , -- 11 TERM , -- 12 FROM_DATE , -- 13 TO_DATE , -- 14 DEPT , -- 15 ACCOUNT_TYPE , -- 16 TERM_TYPE , -- 17 'CHANGE' CHECK_VALUE, -- 18 DEPT ORG_DEPT_CODE, -- 19 ACCOUNT_TYPE ORG_ACCOUNT_TYPE, -- 20 TERM ORG_TERM -- 21 , BUYER , (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = BUYER) AS BUYER_NAME FROM ICOMBDGT WHERE 1=1
AND BUYER = #{st_buyer}
AND BUYER = #{SESSION_BUYER_CODE}
AND DEPT = #{st_dept_code}
AND ACCOUNT_TYPE = #{st_account_type}
AND TERM_TYPE = #{st_term_type}
AND TERM = #{st_term}
ORDER BY DEPT_NAME , ACCOUNT_TYPE_TEXT, TO_DATE DESC ) X )Y

SELECT /*getBuyerMdAmBudgetList_v2*/ ROWNUM AS No, -- 0 Y.DEPT_NAME, -- 1 Y.ACCOUNT_TYPE_TEXT, -- 2 계정분류명 Y.TERM_TYPE_TEXT, -- 3 기간구분 Y.TERM_TEXT, -- 4 Y.PLAN_AMT, -- 5 예산 Y.RESULT_AMT, -- 6 실적금액 Y.TEMP_AMT_TEXT, -- 7 잔액 Y.REMARK , -- 8 비고 CASE WHEN Y.REMARK IS NULL THEN '' ELSE '/resources/imgs/Btn_RegEnd.gif' END AS REMARK_YN, Y.PLAN_DATE , -- 9 예산수립일 Y.LAST_RESULT_DATE , -- 10 최종실적발생일 Y.TEMP_AMT , -- 11 임시실적금액 Y.TERM , -- 12 기간 Y.FROM_DATE , -- 13 시작일 Y.TO_DATE , -- 14 종료일 Y.DEPT , -- 15 부서코드 Y.ACCOUNT_TYPE , -- 16 계정코드 Y.TERM_TYPE , -- 17 기간구분코드 Y.CHECK_VALUE, -- 18 Y.ORG_DEPT_CODE, -- 19 Y.ORG_ACCOUNT_TYPE, -- 20 Y.ORG_TERM -- 21 ,Y.BUYER -- 고객사코드 ,Y.BUYER_NAME -- 고객사명 FROM ( SELECT ROWNUM NUM , X.DEPT_NAME, X.ACCOUNT_TYPE_TEXT, X.TERM_TYPE_TEXT, X.TERM_TEXT, X.PLAN_AMT, X.RESULT_AMT, X.TEMP_AMT_TEXT, X.REMARK, X.PLAN_DATE, X.LAST_RESULT_DATE, X.TEMP_AMT, X.TERM , X.FROM_DATE, X.TO_DATE, X.DEPT, X.ACCOUNT_TYPE, X.TERM_TYPE, X.CHECK_VALUE, X.ORG_DEPT_CODE, X.ORG_ACCOUNT_TYPE, X.ORG_TERM ,X.BUYER ,X.BUYER_NAME FROM ( SELECT (SELECT C.TEXT1 FROM ICOMCOD2 C WHERE C.COMPANY_CODE = BUYER AND C.CODE = DEPT AND C.TYPE = 'C001') DEPT_NAME,-- 1 (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.COMPANY_CODE = BUYER AND C.CODE = ACCOUNT_TYPE AND C.TYPE = 'Z014') ACCOUNT_TYPE_TEXT, -- 2 DECODE(TERM_TYPE,'Y','년','H','반기','Q','분기','M','월','') TERM_TYPE_TEXT, -- 3 SUBSTR(TERM,0,4)||DECODE(SUBSTR(TERM,5,2),'H1','-상반기','H2','-하반기' ,'Q1','-1분기','Q2','-2분기' ,'Q3','-3분기','Q4','-4분기' ,'01','-1월','02','-2월' ,'03','-3월','04','-4월' ,'05','-5월','06','-6월' ,'07','-7월','08','-8월' ,'09','-9월','10','-10월' ,'11','-11월','12','-12월' ,'년') TERM_TEXT, -- 4 NVL(PLAN_AMT,'0') PLAN_AMT, -- 5 NVL(RESULT_AMT,'0') RESULT_AMT, -- 6 NVL(PLAN_AMT,'0') - (NVL(RESULT_AMT,'0')+ NVL(TEMP_AMT,'0')) TEMP_AMT_TEXT, -- 7 REMARK , -- 8 PLAN_DATE , -- 9 LAST_RESULT_DATE , -- 10 NVL(TEMP_AMT,'0') AS TEMP_AMT , -- 11 TERM , -- 12 FROM_DATE , -- 13 TO_DATE , -- 14 DEPT , -- 15 ACCOUNT_TYPE , -- 16 TERM_TYPE , -- 17 'CHANGE' CHECK_VALUE, -- 18 DEPT ORG_DEPT_CODE, -- 19 ACCOUNT_TYPE ORG_ACCOUNT_TYPE, -- 20 TERM ORG_TERM -- 21 , BUYER , (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = BUYER) AS BUYER_NAME FROM ICOMBDGT WHERE 1=1
AND BUYER = #{st_buyer}
AND BUYER = #{SESSION_BUYER_CODE}
AND TERM_TYPE = #{st_term_type}
AND TERM LIKE #{st_year}||'%'
AND TERM = #{st_year}
AND TERM = #{st_term}
AND TERM LIKE #{st_term}||'%'
AND #{st_from_date} <= FROM_DATE AND #{st_to_date} >= TO_DATE ORDER BY DEPT_NAME , ACCOUNT_TYPE_TEXT, TO_DATE DESC ) X WHERE 1=1
AND UPPER(X.DEPT_NAME) LIKE '%'||UPPER(#{st_dept_name})||'%'
AND X.ACCOUNT_TYPE_TEXT LIKE '%'||UPPER(#{st_account_type_text})||'%'
)Y

SELECT BUYER, (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = BUYER) AS BUYER_NAME, DEPT, (SELECT C.TEXT1 FROM ICOMCOD2 C WHERE C.COMPANY_CODE = BUYER AND C.CODE = DEPT AND C.TYPE = 'C001') AS DEPT_NAME, ACCOUNT_TYPE, (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.COMPANY_CODE = BUYER AND C.CODE = ACCOUNT_TYPE AND C.TYPE = 'Z014') ACCOUNT_TYPE_TEXT, TERM, SUBSTR(TERM,0,4)||DECODE(SUBSTR(TERM,5,2), 'H1','년도 상반기','H2','년도 하반기', 'Q1','년도 1/4분기','Q2','년도 2/4분기','Q3','년도 3/4분기','Q4','년도 4/4분기', '01','년도 1월','02','년도 2월','03','년도 3월','04','년도 4월','05','년도 5월','06','년도 6월','07','년도 7월','08','년도 8월','09','년도 9월','10','년도 10월','11','년도 11월','12','년도 12월', '년도' ) AS TERM_TEXT, REVISION, TERM_TYPE, DECODE(TERM_TYPE,'Y','년','H','반기','Q','분기','M','월','') AS TERM_TYPE_TEXT, FROM_DATE, TO_DATE, BEFORE_AMT, CHANGE_AMT, AFTER_AMT, REMARK, TO_CHAR(ADD_DATE, 'YYYY-MM-DD HH24:MI') AS ADD_DATE, ADD_USER_ID, (SELECT C.USER_NAME_LOC FROM ICOMLUSR C WHERE C.USER_ID = ADD_USER_ID) AS ADD_USER_NAME FROM ICOMBDGT_HIST WHERE 1=1
AND BUYER = #{st_buyer}
AND BUYER = #{st_com_code}
AND DEPT = #{st_dept_code}
AND ACCOUNT_TYPE = #{st_account_type}
AND TERM_TYPE = #{st_term_type}
AND TERM = #{st_term}
ORDER BY BUYER, DEPT, ACCOUNT_TYPE, TERM_TYPE, TERM, REVISION

/*excelBuyerMdAmBudgetHistList_v2*/ SELECT A.* FROM ( SELECT BUYER, (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = BUYER) AS BUYER_NAME, DEPT, (SELECT C.TEXT1 FROM ICOMCOD2 C WHERE C.COMPANY_CODE = BUYER AND C.CODE = DEPT AND C.TYPE = 'C001') AS DEPT_NAME, ACCOUNT_TYPE, (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.COMPANY_CODE = BUYER AND C.CODE = ACCOUNT_TYPE AND C.TYPE = 'Z014') ACCOUNT_TYPE_TEXT, TERM, SUBSTR(TERM,0,4)||DECODE(SUBSTR(TERM,5,2), 'H1','-상반기','H2','-하반기', 'Q1','-1분기','Q2','-2분기','Q3','-3분기','Q4','-4분기', '01','-1월','02','-2월','03','-3월','04','-4월','05','-5월','06','-6월','07','-7월','08','-8월','09','-9월','10','-10월','11','-11월','12','-12월', '년도' ) AS TERM_TEXT, REVISION, TERM_TYPE, DECODE(TERM_TYPE,'Y','년','H','반기','Q','분기','M','월','') AS TERM_TYPE_TEXT, FROM_DATE, TO_DATE, BEFORE_AMT, CHANGE_AMT, AFTER_AMT, REMARK, TO_CHAR(ADD_DATE, 'YYYY-MM-DD HH24:MI') AS ADD_DATE, ADD_USER_ID, (SELECT C.USER_NAME_LOC FROM ICOMLUSR C WHERE C.USER_ID = ADD_USER_ID) AS ADD_USER_NAME FROM ICOMBDGT_HIST WHERE 1=1 AND #{st_from_date} <= FROM_DATE AND #{st_to_date} >= TO_DATE
AND BUYER = #{st_buyer}
AND BUYER = #{SESSION_BUYER_CODE}
AND TERM_TYPE = #{st_term_type}
ORDER BY BUYER, DEPT, ACCOUNT_TYPE, TERM_TYPE, TERM, REVISION )A WHERE 1=1
AND UPPER(A.DEPT_NAME) LIKE '%'||UPPER(#{st_dept_name})||'%'
AND A.ACCOUNT_TYPE_TEXT LIKE '%'||UPPER(#{st_account_type_text})||'%'
